class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF Core 9 Cosmos provider now uses sync-over-async by default,
        // but SaveChanges/ToList still work. However, raw SQL queries that reference
        // "Discriminator" must be updated if the app doesn't set HasJsonPropertyName above.
        // Since we preserved "Discriminator" in OnModelCreating, raw SQL like
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // continues to work unchanged.

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

